begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('da000000-0000-4000-8000-000000000001','lab-staff@example.test','{"first_name":"Lab","last_name":"Staff"}'),('da000000-0000-4000-8000-000000000002','lab-inactive@example.test','{"first_name":"Inactive","last_name":"Staff"}');
update public.profiles set is_active = true where id in ('da000000-0000-4000-8000-000000000001','da000000-0000-4000-8000-000000000002');
insert into public.user_roles (user_id, role) values ('da000000-0000-4000-8000-000000000001','STAFF'),('da000000-0000-4000-8000-000000000002','STAFF');

update public.profiles set is_active=false where id='da000000-0000-4000-8000-000000000002';
create temp table lab_fixture(kind text primary key,id uuid);grant all on lab_fixture to authenticated;
select ok(not has_table_privilege('authenticated','public.patient_lab_orders','UPDATE'),'Direct lab updates denied');
select ok(not has_table_privilege('service_role','public.patient_lab_orders','DELETE'),'Service cannot delete native orders');
select ok(not has_table_privilege('authenticated','public.lab_work_revisions','UPDATE'),'History immutable');
select ok(not has_table_privilege('anon','public.patient_lab_orders','SELECT'),'Anonymous access denied');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"da000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into lab_fixture select 'client',id from public.save_client(auth.uid(),null,null,'Synthetic','Lab',null,null,'EMAIL',null,null);
insert into lab_fixture select 'pet',id from public.save_patient(null,(select id from lab_fixture where kind='client'),null,'One','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into lab_fixture select 'other',id from public.save_patient(null,(select id from lab_fixture where kind='client'),null,'Two','Cat',null,null,'unknown',null,'unknown','unknown',null,null,null);
select throws_ok($$select public.save_lab_due_template(gen_random_uuid(),null,'Reviewed test',30,true,'Dr reviewer')$$,'42501',null,'Non-admin cannot standardize clinical intervals');
reset role;
insert into public.user_roles(user_id,role) values('da000000-0000-4000-8000-000000000001','ADMIN') on conflict do nothing;
set local role authenticated;
select lives_ok($$select public.save_lab_due_template('da100000-0000-4000-8000-000000000001',null,'Reviewed test',30,true,'Synthetic clinical reviewer rationale')$$,'Admin records reviewed interval');
select lives_ok($$select public.save_lab_due_template('da100000-0000-4000-8000-000000000001',null,'Reviewed test',30,true,'Synthetic clinical reviewer rationale')$$,'Template retry idempotent');
select is((select count(*) from public.lab_work_revisions where entity='template'),1::bigint,'No duplicate template history');
select throws_ok($$select public.save_lab_due_template(gen_random_uuid(),null,'Bad',0,true,'Reviewed')$$,'23514',null,'Zero interval rejected');
select throws_ok($$select public.save_lab_due_template(gen_random_uuid(),null,'Bad',10,true,'')$$,'23514',null,'Clinical review rationale required');
create function pg_temp.lab_save(p_id uuid,p_version integer,p_data jsonb,p_reason text default '') returns public.patient_lab_orders language sql as $$select public.save_patient_lab_order(p_id,(select id from lab_fixture where kind='pet'),p_version,p_data,p_reason)$$;
select lives_ok($$select pg_temp.lab_save('da200000-0000-4000-8000-000000000001',null,'{"test_name":"Chemistry","status":"planned","due_date":"2026-10-01"}')$$,'Create native planned test');
select lives_ok($$select pg_temp.lab_save('da200000-0000-4000-8000-000000000001',null,'{"test_name":"Chemistry","status":"planned","due_date":"2026-10-01"}')$$,'Order retry idempotent');
select is((select count(*) from public.lab_work_revisions where entity='order'),1::bigint,'No duplicate order history');
select throws_ok($$select public.save_patient_lab_order('da200000-0000-4000-8000-000000000001',(select id from lab_fixture where kind='other'),1,'{"test_name":"Bad","status":"ordered"}','')$$,'42501',null,'Cross patient update rejected');
select throws_ok($$select pg_temp.lab_save('da200000-0000-4000-8000-000000000001',0,'{"test_name":"Changed","status":"ordered"}')$$,'40001',null,'Stale edits rejected');
select throws_ok($$select pg_temp.lab_save(gen_random_uuid(),null,'{"test_name":"Bad","status":"planned","due_date":"infinity"}')$$,'23514',null,'Infinite due date rejected');
select throws_ok($$select pg_temp.lab_save(gen_random_uuid(),null,'{"test_name":"Bad","status":"resulted"}')$$,'23514',null,'Result status requires real dates');
select throws_ok($$select pg_temp.lab_save(gen_random_uuid(),null,'{"test_name":"Bad","status":"collected","collected_date":"2999-01-01"}')$$,'23514',null,'Future collection rejected');
select throws_ok($$select pg_temp.lab_save(gen_random_uuid(),null,'{"test_name":"Bad","status":"planned","template_id":"da100000-0000-4000-8000-000000000001","template_version":1,"interval_days":14,"interval_anchor":"2026-01-01","due_date":"2026-01-15"}')$$,'23514',null,'Patient interval override requires rationale');
select lives_ok($$select pg_temp.lab_save('da200000-0000-4000-8000-000000000002',null,'{"test_name":"Override","status":"planned","template_id":"da100000-0000-4000-8000-000000000001","template_version":1,"interval_days":14,"interval_anchor":"2026-01-01","due_date":"2026-01-15","override_reason":"Reviewed patient-specific follow-up"}')$$,'Explicit patient override saved');
select throws_ok($$select pg_temp.lab_save(gen_random_uuid(),null,'{"test_name":"Bad","status":"planned","interval_days":14,"interval_anchor":"2026-01-01","due_date":"2026-01-20"}')$$,'23514',null,'Due date must match reviewed arithmetic');
select lives_ok($$select public.save_lab_due_template('da100000-0000-4000-8000-000000000001',1,'Reviewed test',60,false,'Retired after clinical review')$$,'Template revisions retained');
select is((select interval_days from public.patient_lab_orders where id='da200000-0000-4000-8000-000000000002'),14,'Template edits never change patient plan');
select lives_ok($$select pg_temp.lab_save('da200000-0000-4000-8000-000000000002',1,'{"test_name":"Override","status":"ordered","template_id":"da100000-0000-4000-8000-000000000001","template_version":1,"interval_days":14,"interval_anchor":"2026-01-01","due_date":"2026-01-15","override_reason":"Reviewed patient-specific follow-up"}')$$,'Existing provenance survives retirement');
select throws_ok($$select pg_temp.lab_save(gen_random_uuid(),null,'{"test_name":"Bad","status":"planned","template_id":"da100000-0000-4000-8000-000000000001","template_version":1,"interval_days":30,"interval_anchor":"2026-01-01","due_date":"2026-01-31"}')$$,'40001',null,'Retired template cannot be newly applied');
select throws_ok($$select pg_temp.lab_save('da200000-0000-4000-8000-000000000001',1,'{"test_name":"Chemistry","status":"planned","template_id":"da100000-0000-4000-8000-000000000001","template_version":1,"interval_days":30,"interval_anchor":"2026-01-01","due_date":"2026-01-31"}')$$,'40001',null,'Existing manual order cannot bypass retired template validation with null provenance');
reset role;
insert into public.patient_documents(id,pet_id,file_name,file_path,mime_type,file_size,category,source,visibility,status,created_by) values('da300000-0000-4000-8000-000000000001',(select id from lab_fixture where kind='other'),'other.pdf','synthetic/other.pdf','application/pdf',10,'lab_result','synthetic','internal','ready','da000000-0000-4000-8000-000000000001'),('da300000-0000-4000-8000-000000000002',(select id from lab_fixture where kind='pet'),'pending.pdf','synthetic/pending.pdf','application/pdf',10,'lab_result','synthetic','internal','uploading','da000000-0000-4000-8000-000000000001');
set local role authenticated;
select throws_ok($$select pg_temp.lab_save(gen_random_uuid(),null,'{"test_name":"Bad","status":"planned","result_document_id":"da300000-0000-4000-8000-000000000001"}')$$,'42501',null,'Another patient document rejected');
select throws_ok($$select pg_temp.lab_save(gen_random_uuid(),null,'{"test_name":"Bad","status":"planned","result_document_id":"da300000-0000-4000-8000-000000000002"}')$$,'42501',null,'Pending document rejected');
select lives_ok($$select pg_temp.lab_save('da200000-0000-4000-8000-000000000001',1,'{"test_name":"Chemistry","status":"resulted","collected_date":"2026-01-01","result_date":"2026-01-02","notes":"Manually transcribed observation"}')$$,'Record result without machine interpretation');
select throws_ok($$select pg_temp.lab_save('da200000-0000-4000-8000-000000000001',2,'{"test_name":"Chemistry","status":"resulted","collected_date":"2026-01-01","result_date":"2026-01-02","notes":"Changed"}')$$,'23514',null,'Cannot silently overwrite result');
select lives_ok($$select pg_temp.lab_save('da200000-0000-4000-8000-000000000001',2,'{"test_name":"Chemistry","status":"resulted","collected_date":"2026-01-01","result_date":"2026-01-02","notes":"Corrected observation"}','Correction after source review')$$,'Explicit correction accepted');
select is((select snapshot->>'notes' from public.lab_work_revisions where entity_id='da200000-0000-4000-8000-000000000001' and version=2),'Manually transcribed observation','Original result remains in immutable history');
select is((select updated_by from public.patient_lab_orders where id='da200000-0000-4000-8000-000000000001'),auth.uid(),'Server stamps authenticated actor');
select set_config('request.jwt.claims','{"sub":"da000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*) from public.patient_lab_orders),0::bigint,'Inactive staff cannot read labs');
select throws_ok($$select pg_temp.lab_save(gen_random_uuid(),null,'{"test_name":"Blocked","status":"planned"}')$$,'42501',null,'Inactive actor cannot save labs');
select * from finish();rollback;
